<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Http\Request;
class Cors { public function handle(Request $request, Closure $next){$allowed=array_filter([env('FRONTEND_URL','http://localhost:5173'),env('ADMIN_URL','http://localhost:5174')]);$origin=$request->headers->get('Origin');if($request->getMethod()==='OPTIONS'){return response('',204)->withHeaders(['Access-Control-Allow-Origin'=>in_array($origin,$allowed,true)?$origin:'*','Access-Control-Allow-Methods'=>'GET, POST, PUT, DELETE, OPTIONS','Access-Control-Allow-Headers'=>'Content-Type, Authorization, Accept']);}$response=$next($request);if($origin&&in_array($origin,$allowed,true))$response->headers->set('Access-Control-Allow-Origin',$origin);$response->headers->set('Access-Control-Allow-Headers','Content-Type, Authorization, Accept');$response->headers->set('Access-Control-Allow-Methods','GET, POST, PUT, DELETE, OPTIONS');return $response;} }
